export function getShowById(id: string): Show | undefined {
  return SHOWS.find((show) => show.id === id);
}

export function getShowsByMood(
  mood: string,
  availableMinutes: number,
  watchingWith?: string
): Show[] {
  return SHOWS.filter((show) => {
    const moodMatch = show.moodTags.includes(mood as any);
    const watchingMatch =
      !watchingWith || show.watchingWithTags.includes(watchingWith as any);
    return moodMatch && watchingMatch;
  }).sort((a, b) => {
    const aFits = a.avgEpisodeMinutes <= availableMinutes ? 1 : 0;
    const bFits = b.avgEpisodeMinutes <= availableMinutes ? 1 : 0;
    if (aFits !== bFits) return bFits - aFits;
    return b.worthItScore - a.worthItScore;
  });
}

export function getFeaturedShow(): Show {
  return SHOWS.find((s) => s.id === 'squid-game')!;
}

export function computeFitScore(
  show: Show,
  mood: string,
  availableMinutes: number,
  watchingWith: string
): number {
  let score = 0;

  // Mood match: weighted by position in moodTags — primary tag gets
  // full 32 points, each subsequent tag decays so a show whose dominant
  // tone matches the selected mood ranks above one where it's secondary.
  const moodIdx = show.moodTags.indexOf(mood as any);
  if (moodIdx === 0) {
    score += 32;
  } else if (moodIdx > 0) {
    score += Math.round((32 - moodIdx * 7) * 10) / 10;
  } else {
    score += 8;
  }

  // Time fit: proportional to how comfortably the episode fits,
  // scaled 0–24. A perfect fit (episode ≈ 40-70% of available time)
  // scores higher than one that barely squeaks under the budget.
  if (show.avgEpisodeMinutes <= availableMinutes) {
    const ratio = show.avgEpisodeMinutes / availableMinutes;
    const comfort = ratio >= 0.4 && ratio <= 0.7 ? 1 : Math.min(1, ratio / 0.4);
    score += 16 + comfort * 8;
  } else if (show.avgEpisodeMinutes <= availableMinutes * 1.3) {
    score += 12;
  }

  // Group match: 24 points (full) or 4 (no match)
  const groupMatch = show.watchingWithTags.includes(watchingWith as any);
  score += groupMatch ? 24 : 4;

  // Quality tiebreaker: blend worthItScore (0-100) and rating (0-10)
  // as fractional points so shows with identical mood/time/who matches
  // still get distinct scores. Uses one decimal place of precision.
  const qualityBonus = (show.worthItScore / 100) * 15 + (show.rating / 10) * 5;
  score += qualityBonus;

  return Math.min(100, Math.round(score * 10) / 10);
}
